import sharp from "sharp";
import path from "path";
import { fileURLToPath } from "url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(__dirname, "..");
const brand = path.join(root, "public", "brand");
const assets = path.join(
  "c:",
  "Users",
  "yarde",
  ".cursor",
  "projects",
  "c-Users-yarde-OneDrive-Desktop-MAZAL",
  "assets",
);

const customerSrc = path.join(
  assets,
  "c__Users_yarde_AppData_Roaming_Cursor_User_workspaceStorage_af2d1dcb79e6f8c63e030ba190e0ce95_images_logo-a926aae1-324b-4735-b841-80db91a94044.png",
);
const adminSrc = path.join(
  assets,
  "c__Users_yarde_AppData_Roaming_Cursor_User_workspaceStorage_af2d1dcb79e6f8c63e030ba190e0ce95_images_logo3-da409f9e-c517-41d1-af69-e0286ebf961c.png",
);

async function writeSizes(sizes, src, baseName) {
  for (const s of sizes) {
    await sharp(src)
      .resize(s, s, { fit: "cover", position: "centre" })
      .png()
      .toFile(path.join(brand, `${baseName}-${s}.png`));
    console.log("wrote", `${baseName}-${s}.png`);
  }
}

await writeSizes([180, 192, 512], customerSrc, "mazal-app-icon");
await writeSizes([180, 192, 512], adminSrc, "mazal-admin-icon");
console.log("done");

